if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_bsf() {
    _helper_ffmpeg_list -bsfs | gawk '
        /^Bitstream filters:/ { data = 1; next }
        data && NF == 1 { print $1 }
    '
}

_choice_channel_layout() {
    _helper_ffmpeg_list -layouts | gawk '
        /^Standard channel layouts:/ { data = 1; next }
        data && NF >= 2 { printf "%s\t%s\n", $1, $2 }
    '
}

_choice_codec() {
    { _helper_ffmpeg_list -codecs; _helper_ffmpeg_list -encoders; _helper_ffmpeg_list -decoders; } | gawk '
        /^[A-Za-z].*:$/ { data = 0; next }
        /^ +-+ *$/ { data = 1; next }
        data && NF >= 2 {
            name = $2
            if (seen[name]++) next
            desc = $0
            sub(/^ *[^ ]+ +[^ ]+ */, "", desc)
            if (desc == "") print name
            else printf "%s\t%s\n", name, desc
        }
    '
    printf 'copy\tStream copy without re-encoding\n'
}

_choice_cpuflags() {
    printf '%s\n' \
        0 3dnow 3dnowext altivec armv5te armv6 armv6t2 armv8 athlon athlonxp \
        atom avx avx2 bmi1 bmi2 cmov fma3 fma4 k6 k62 k8 mmx mmxext neon \
        pentium2 pentium3 pentium4 setend sse sse2 sse2slow sse3 sse3slow \
        sse4.1 sse4.2 ssse3 vfp vfpv3 xop
}

_choice_device() {
    _helper_ffmpeg_list -devices | gawk '
        /^ ---/ { data = 1; next }
        data && NF >= 2 {
            desc = $0
            sub(/^ *[^ ]+ +[^ ]+ */, "", desc)
            count = split($2, names, ",")
            for (i = 1; i <= count; i++) {
                if (desc == "") print names[i]
                else printf "%s\t%s\n", names[i], desc
            }
        }
    '
}

_choice_disposition() {
    _helper_ffmpeg_list -dispositions | gawk 'NF { print $1 }'
}

_choice_filter() {
    _helper_ffmpeg_list -filters | gawk '
        /^ *-+ *$/ { data = 1; next }
        data && NF >= 4 {
            desc = $0
            sub(/^ *[^ ]+ +[^ ]+ +[^ ]+ +/, "", desc)
            if (desc == "") printf "%s\0\n", $2
            else printf "%s\0\t%s\n", $2, desc
        }
    '
}

_choice_format() {
    _helper_ffmpeg_list -formats | gawk '
        /^ +-+ *$/ { data = 1; next }
        data && NF >= 2 {
            desc = $0
            sub(/^ *[^ ]+ +[^ ]+ */, "", desc)
            count = split($2, names, ",")
            for (i = 1; i <= count; i++) {
                if (desc == "") print names[i]
                else printf "%s\t%s\n", names[i], desc
            }
        }
    '
}

_choice_input_index() {
    local i
    for i in "${!argc_i[@]}"; do
        printf '%s\n' "$i"
    done
    printf '%s\n' '-1'
}

_choice_loglevel() {
    cat <<'EOF'
quiet	Show nothing at all
panic	Only show fatal errors which could lead the process to crash
fatal	Only show fatal errors
error	Show all errors, including ones which can be recovered from
warning	Show all warnings and errors
info	Show informative messages during processing
verbose	Same as "info", except more verbose
debug	Show everything, including debugging information
trace	Show all debugging information
repeat	Do not compress repeated log output
level	Add a "[level]" prefix to each message line
time	Prefix log lines with time information
datetime	Prefix log lines with date and time information
EOF
}

_choice_map() {
    local i
    for i in "${!argc_i[@]}"; do
        printf '%s\n' "$i" "$i:v" "$i:a" "$i:s" "$i:d" "$i:t"
    done
    printf '%s\n' '-1'
}

_choice_pass() {
    printf '%s\n' 1 2
}

_choice_path() {
    _argc_util_comp_path
}

_choice_pix_fmt() {
    _helper_ffmpeg_list -pix_fmts | gawk '
        /^-----/ { data = 1; next }
        data && NF >= 5 {
            printf "%s\t%s components, %s bpp, depth %s\n", $2, $3, $4, $5
        }
        data && NF >= 2 { if (NF < 5) print $2 }
    '
}

_choice_sample_fmt() {
    _helper_ffmpeg_list -sample_fmts | gawk '
        NR > 1 && NF >= 2 { printf "%s\tdepth %s\n", $1, $2 }
    '
}

_choice_sws_flags() {
    cat <<'EOF'
fast_bilinear	Fast bilinear scaling (deprecated)
bilinear	Bilinear scaling (deprecated)
bicubic	Bicubic scaling (deprecated)
experimental	Experimental scaling (deprecated)
neighbor	Nearest neighbor rescaling (deprecated)
area	Averaging area rescaling (deprecated)
bicublin	Bicubic luma, bilinear chroma scaling (deprecated)
gauss	Gaussian rescaling (deprecated)
sinc	Sinc rescaling (deprecated)
lanczos	Lanczos rescaling (deprecated)
spline	Natural bicubic spline rescaling (deprecated)
print_info	Enable printing/debug logging
accurate_rnd	Enable accurate rounding
full_chroma_int	Enable full chroma interpolation
full_chroma_inp	Select full chroma input
bitexact	Enable bitexact output
unstable	Allow the use of experimental new code
EOF
}

_choice_target() {
    printf '%s\n' vcd svcd dvd dv dv50
}

_helper_ffmpeg_list() {
    command ffmpeg -hide_banner -nostdin "$@" 2>/dev/null
}
